import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/evaluation-and-environment/","title":"CH1.9 评价、环境与能源 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.9 评价、环境与能源","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/evaluation-and-environment/"},"readingTime":{"minutes":28.99,"words":8697},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/9.evaluation-and-environment.md","headers":[],"bulletin":false}`),a={name:`9.evaluation-and-environment.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="splendid" tabindex="-1"><a class="header-anchor" href="#splendid"><span>Splendid</span></a></h2><p class="vc-meta"><strong>/ˈsplendɪd/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>壮丽的，辉煌的</li><li>（口语）极好的，很棒的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a splendid view</td><td>壮丽的景色</td></tr><tr><td>a splendid idea</td><td>绝妙的主意</td></tr><tr><td>splendid isolation</td><td>光荣孤立（政治习语）</td></tr><tr><td>splendid weather</td><td>极好的天气</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a splendid view over the valley from the ridge.</p><blockquote><p>照片显示了从山脊俯瞰山谷的壮丽景色。</p></blockquote><p><strong>Writing Task 2</strong> The cathedral&#39;s splendid facade draws millions of visitors each year.</p><blockquote><p>大教堂壮丽的立面每年吸引数百万游客。</p></blockquote><p><strong>Speaking</strong> We had a splendid time — thanks for asking.</p><blockquote><p>我们玩得非常开心，谢谢关心。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>magnificent</td><td>壮丽的</td><td>语气更强，多形容建筑、景观</td></tr><tr><td>superb</td><td>极好的</td><td>偏口语，夸质量</td></tr><tr><td>gorgeous</td><td>绚丽的</td><td>多形容外观、天气</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>splendidus</em> ← <em>splendere</em>（发光）</li><li><strong>Family:</strong> splendid 壮丽的 / splendour 辉煌 / resplendent 灿烂的</li><li><strong>Memory Tip:</strong> splendere = 发光。由&quot;闪闪发光&quot;引申为&quot;壮丽&quot;，再口语化为&quot;极好的&quot;——一条词义外扩的典型路径。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>口语表&quot;很好&quot;（Splendid!），正式写作表&quot;壮丽&quot;，语气差别要把握。</li><li>拼写 splen-did，注意中间是 -en-。</li><li>形容建筑用 magnificent 更常见，splendid 偏英式。</li></ul></div><div class="vocab-card"><h2 id="grand" tabindex="-1"><a class="header-anchor" href="#grand"><span>Grand</span></a></h2><p class="vc-meta"><strong>/ɡrænd/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>宏伟的，壮丽的</li><li>重大的，宏大的</li><li>（口语，名词）一千英镑／一千美元</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a grand building</td><td>宏伟的建筑</td></tr><tr><td>the grand total</td><td>总计</td></tr><tr><td>a grand plan</td><td>宏大的计划</td></tr><tr><td>on a grand scale</td><td>大规模地</td></tr><tr><td>ten grand</td><td>一万（口语）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the grand scale of the irrigation scheme.</p><blockquote><p>该地图显示了该灌溉工程的宏大范围。</p></blockquote><p><strong>Writing Task 2</strong> Grand declarations rarely survive contact with local budgets.</p><blockquote><p>宏大的宣言很少能经得住地方预算的检验。</p></blockquote><p><strong>Speaking</strong> They live in a grand old house near the park.</p><blockquote><p>他们住在公园附近一栋气派的老房子里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>imposing</td><td>气势宏伟的</td><td>强调压迫感、体量</td></tr><tr><td>majestic</td><td>庄严的</td><td>带敬意，多形容自然、王室</td></tr><tr><td>ambitious</td><td>宏大的</td><td>多形容计划、目标</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>grandis</em>（大的）</li><li><strong>Family:</strong> grand 宏伟的 / grandeur 壮丽 / grandly 宏伟地 / grandiose 浮夸的</li><li><strong>Memory Tip:</strong> 同根三个词语气递进：grand（宏大）→ grandeur（壮丽，名词）→ grandiose（浮夸，贬义）。夸人用 grand，贬人用 grandiose。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>the grand total 是&quot;总计&quot;，不是&quot;宏大的总数&quot;。</li><li>口语 ten grand 指一万块钱，正式文里别用。</li><li>grandiose 带贬义，不能用来夸建筑。</li></ul></div><div class="vocab-card"><h2 id="magnificent" tabindex="-1"><a class="header-anchor" href="#magnificent"><span>Magnificent</span></a></h2><p class="vc-meta"><strong>/mæɡˈnɪfɪsnt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>壮丽的，宏伟的</li><li>极好的，了不起的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a magnificent building</td><td>宏伟的建筑</td></tr><tr><td>magnificent scenery</td><td>壮丽的风景</td></tr><tr><td>a magnificent achievement</td><td>了不起的成就</td></tr><tr><td>magnificently</td><td>壮丽地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows a magnificent waterfall dropping into the gorge.</p><blockquote><p>照片显示一道壮丽的瀑布落入峡谷。</p></blockquote><p><strong>Writing Task 2</strong> The dam was a magnificent engineering achievement with a heavy ecological cost.</p><blockquote><p>这座大坝是一项了不起的工程成就，但生态代价沉重。</p></blockquote><p><strong>Speaking</strong> The view from the top was absolutely magnificent.</p><blockquote><p>山顶的景色真是壮丽极了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>splendid</td><td>壮丽的</td><td>偏英式，语气稍轻</td></tr><tr><td>breathtaking</td><td>令人屏息的</td><td>强调震撼感</td></tr><tr><td>imposing</td><td>雄伟的</td><td>强调体量与气势</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>magnificus</em> = <em>magnus</em>（大）+ <em>facere</em>（做）→ &quot;做得很大&quot;</li><li><strong>Family:</strong> magnificent 壮丽的 / magnificence 壮丽 / magnify 放大 / magnitude 量级</li><li><strong>Memory Tip:</strong> magnus（大）+ facere（做）。同根一串：magnify 放大、magnitude 量级、magnate 巨头。magnificent 就是&quot;做得极其宏大&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 mag-ni-fi-cent，注意 -fic- 而非 <s>-fac-</s>。</li><li>语气很强，别用来形容小事。</li><li>名词是 magnificence，不是 <s>magnificency</s>。</li></ul></div><div class="vocab-card"><h2 id="super" tabindex="-1"><a class="header-anchor" href="#super"><span>Super</span></a></h2><p class="vc-meta"><strong>/ˈsuːpə(r)/</strong> · adj · 形容词 / adv · 副词 / prefix · 前缀</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：（口语）极好的，很棒的</li><li>副词：（口语）非常</li><li>前缀：超，超级</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>super fast</td><td>超快</td></tr><tr><td>the super-rich</td><td>超级富豪</td></tr><tr><td>a superpower</td><td>超级大国</td></tr><tr><td>a supermarket</td><td>超市</td></tr><tr><td>super-thin</td><td>超薄的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a super-regional shopping centre on the ring road.</p><blockquote><p>该地图显示了环路旁的一座超区域购物中心。</p></blockquote><p><strong>Writing Task 2</strong> Super-thin plastic film is now banned in many countries because it cannot be recycled.</p><blockquote><p>超薄塑料膜因无法回收，现已在许多国家被禁用。</p></blockquote><p><strong>Speaking</strong> The film was super good — you should watch it.</p><blockquote><p>那部电影超好看，你应该去看。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>excellent</td><td>优秀的</td><td>正式，适合写作</td></tr><tr><td>superb</td><td>极好的</td><td>比 super 正式一些</td></tr><tr><td>outstanding</td><td>出色的</td><td>强调突出、卓越</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>super</em>（在上、超过）</li><li><strong>Family:</strong> super 极好的 / superb 卓越的 / superior 更好的 / supermarket 超市 / supersonic 超音速的</li><li><strong>Memory Tip:</strong> 作前缀表&quot;超&quot;：supermarket、superpower、supernatural、supersonic。作形容词是口语&quot;超棒&quot;，正式写作里换成 excellent。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词用法偏口语，学术写作改用 excellent / superb。</li><li>superb 结尾是 -b，不是 <s>superbe</s>。</li><li>superior 后接 to，不用 than。</li></ul></div><div class="vocab-card"><h2 id="interesting" tabindex="-1"><a class="header-anchor" href="#interesting"><span>Interesting</span></a></h2><p class="vc-meta"><strong>/ˈɪntrəstɪŋ/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>有趣的，引人关注的</li><li>值得注意的（学术语境）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an interesting point</td><td>一个有意思的观点</td></tr><tr><td>it is interesting that</td><td>值得注意的是</td></tr><tr><td>interestingly</td><td>有趣的是</td></tr><tr><td>find something interesting</td><td>觉得某事有意思</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows an interesting contrast between the two regions.</p><blockquote><p>该图表显示了两个地区之间一个值得注意的对比。</p></blockquote><p><strong>Writing Task 2</strong> It is interesting that the policy worked better in rural areas than in cities.</p><blockquote><p>有意思的是，该政策在农村地区比在城市更奏效。</p></blockquote><p><strong>Speaking</strong> That&#39;s interesting — I&#39;d never thought of it that way.</p><blockquote><p>这挺有意思，我从没这么想过。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fascinating</td><td>迷人的</td><td>语气强，真正吸引人</td></tr><tr><td>intriguing</td><td>引人入胜的</td><td>强调引发好奇</td></tr><tr><td>noteworthy</td><td>值得注意的</td><td>学术，最稳妥</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>interest</em>（兴趣）+ <em>-ing</em></li><li><strong>Family:</strong> interesting 有趣的 / interested 感兴趣的 / interest 兴趣 / disinterested 无私的</li><li><strong>Memory Tip:</strong> -ing 修饰&quot;引起感受的事物&quot;（The book is interesting），-ed 修饰&quot;人的感受&quot;（I&#39;m interested）。这是中国学生最高频的一处错。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>别说 <s>I&#39;m interesting in</s>，应为 I&#39;m interested in。</li><li>interesting 形容物，interested 形容人。</li><li>学术写作里 interesting 偏弱，用 noteworthy / significant 更有分量。</li></ul></div><div class="vocab-card"><h2 id="dramatic" tabindex="-1"><a class="header-anchor" href="#dramatic"><span>Dramatic</span></a></h2><p class="vc-meta"><strong>/drəˈmætɪk/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>急剧的，显著的（变化、增长）</li><li>戏剧性的，夸张的</li><li>壮观的（景色）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a dramatic increase</td><td>急剧增长</td></tr><tr><td>a dramatic change</td><td>显著变化</td></tr><tr><td>dramatic scenery</td><td>壮观的景色</td></tr><tr><td>dramatic effect</td><td>戏剧性效果</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows a dramatic fall in coal use after 2015.</p><blockquote><p>该图表显示 2015 年后煤炭使用量急剧下降。</p></blockquote><p><strong>Writing Task 2</strong> The most dramatic consequence of warming is the retreat of Arctic sea ice.</p><blockquote><p>气候变暖最显著的后果是北极海冰的退缩。</p></blockquote><p><strong>Speaking</strong> There was a dramatic improvement in her health within a week.</p><blockquote><p>一周之内她的健康状况就有了明显好转。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sharp</td><td>急剧的</td><td>图表题最常用，指幅度大</td></tr><tr><td>striking</td><td>显著的</td><td>强调引人注目</td></tr><tr><td>theatrical</td><td>戏剧化的</td><td>带&quot;做作&quot;意味</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>drama</em>（动作、戏剧）</li><li><strong>Family:</strong> dramatic 急剧的；戏剧的 / dramatically 急剧地 / drama 戏剧 / dramatise 改编成戏剧</li><li><strong>Memory Tip:</strong> 图表题里 dramatically 就是&quot;急剧地&quot;，比 a lot 高级得多：increased dramatically。Task 1 想拿高分，这个词几乎是必需品。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>图表语境中 dramatic = sharp，不是&quot;戏剧的&quot;。</li><li>副词 dramatically：rose dramatically。</li><li>与 drastic 区分：drastic 多指&quot;激烈的措施&quot;，dramatic 指&quot;变化幅度大&quot;。</li></ul></div><div class="vocab-card"><h2 id="inevitable" tabindex="-1"><a class="header-anchor" href="#inevitable"><span>Inevitable</span></a></h2><p class="vc-meta"><strong>/ɪnˈevɪtəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>不可避免的，必然发生的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an inevitable consequence</td><td>必然的后果</td></tr><tr><td>it is inevitable that</td><td>……是不可避免的</td></tr><tr><td>the inevitable result</td><td>必然结果</td></tr><tr><td>accept the inevitable</td><td>接受不可避免之事</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph suggests that a rise in demand is inevitable by 2030.</p><blockquote><p>该图显示到 2030 年需求上升将不可避免。</p></blockquote><p><strong>Writing Task 2</strong> Some warming is now inevitable, but its worst effects are not.</p><blockquote><p>一定程度的变暖如今已不可避免，但其最坏的后果并非必然。</p></blockquote><p><strong>Speaking</strong> Delays were inevitable given the weather.</p><blockquote><p>天气这样，延误是免不了的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>unavoidable</td><td>无法避免的</td><td>更口语，语气稍轻</td></tr><tr><td>certain</td><td>必然的</td><td>强调确定性，非&quot;躲不掉&quot;</td></tr><tr><td>inescapable</td><td>逃脱不了的</td><td>书面，语气最强</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>in-</em>（不）+ <em>evitare</em>（避开）→ <em>inevitabilis</em></li><li><strong>Family:</strong> inevitable 不可避免的 / inevitably 必然地 / inevitability 必然性</li><li><strong>Memory Tip:</strong> e-（出）+ vitare（避开）= 想躲躲不掉。Task 2 里 It is inevitable that… 是很好用的句式，比 Everyone knows that… 更学术。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 in-ev-it-able，注意只有一个 n。</li><li>副词 inevitably 常置于句首：Inevitably, costs rose.</li><li>不能说 <s>inevitable of</s>，接名词时用 an inevitable result of。</li></ul></div><div class="vocab-card"><h2 id="irreversible" tabindex="-1"><a class="header-anchor" href="#irreversible"><span>Irreversible</span></a></h2><p class="vc-meta"><strong>/ˌɪrɪˈvɜːsəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>不可逆的，无法挽回的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>irreversible damage</td><td>不可逆的损害</td></tr><tr><td>irreversible change</td><td>不可逆转的变化</td></tr><tr><td>an irreversible decline</td><td>无法挽回的衰退</td></tr><tr><td>become irreversible</td><td>变得不可逆</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows that once the ice sheet passes a threshold, the loss becomes irreversible.</p><blockquote><p>该图表显示，冰盖一旦越过某个临界点，其消融就变得不可逆转。</p></blockquote><p><strong>Writing Task 2</strong> Some forms of environmental damage are effectively irreversible within a human lifetime.</p><blockquote><p>某些环境损害在人的一生之内实际上是无法逆转的。</p></blockquote><p><strong>Speaking</strong> The damage to my knee is irreversible, so I&#39;ve had to give up running.</p><blockquote><p>我膝盖的损伤不可逆，只好放弃跑步。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>permanent</td><td>永久的</td><td>强调持续，非&quot;无法回头&quot;</td></tr><tr><td>irreparable</td><td>无法修复的</td><td>强调损坏不可修补</td></tr><tr><td>irrecoverable</td><td>无法恢复的</td><td>多用于损失、成本</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>ir-</em>（不）+ <em>re-</em>（回）+ <em>vers</em>（转）+ <em>-ible</em>（能……的）→ &quot;转不回去的&quot;</li><li><strong>Family:</strong> irreversible 不可逆的 / reverse 逆转；相反的 / reversibility 可逆性 / reversible 可逆的</li><li><strong>Memory Tip:</strong> vers = 转（同 convert、reverse、versus）。re + vers = 转回去；加 ir- 和 -ible 就成了&quot;转不回去&quot;。气候临界点话题的核心词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 ir-re-vers-ible，前缀双 r。</li><li>固定搭配是 irreversible damage / irreversible change。</li><li>别与 irreplaceable（不可替代）混，后者讲&quot;独一无二&quot;。</li></ul></div><div class="vocab-card"><h2 id="irregularly" tabindex="-1"><a class="header-anchor" href="#irregularly"><span>Irregularly</span></a></h2><p class="vc-meta"><strong>/ɪˈreɡjələli/</strong> · adv · 副词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>不规则地（形状、分布）</li><li>不定期地，无规律地（时间、频率）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>irregularly shaped</td><td>形状不规则的</td></tr><tr><td>irregularly spaced</td><td>间隔不均的</td></tr><tr><td>irregularly distributed</td><td>分布不均的</td></tr><tr><td>occur irregularly</td><td>不定期发生</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows irregularly shaped fields along the floodplain.</p><blockquote><p>该地图显示了沿洪泛平原分布的形状不规则的地块。</p></blockquote><p><strong>Writing Task 2</strong> Rainfall now arrives more irregularly than it did a century ago.</p><blockquote><p>如今降水的规律性远不如一个世纪前。</p></blockquote><p><strong>Speaking</strong> The trains run irregularly at weekends.</p><blockquote><p>周末火车班次不规律。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>unevenly</td><td>不均匀地</td><td>强调分布差异</td></tr><tr><td>sporadically</td><td>零散地</td><td>强调偶发、不连续</td></tr><tr><td>erratically</td><td>反复无常地</td><td>带&quot;不可预测&quot;意味</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>ir-</em>（不）+ <em>regular</em>（规则的）+ <em>-ly</em></li><li><strong>Family:</strong> irregular 不规则的 / irregularity 不规则 / regularly 定期地 / regulate 管理，调节</li><li><strong>Memory Tip:</strong> 形容词 irregular + ly 变副词。描述地图上&quot;形状不规则、分布不均&quot;时，irregularly shaped / distributed 比 not regular 专业得多。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容词是 irregular，副词才是 irregularly。</li><li>irregular（不规则）与 illegal（非法）完全不同，别混。</li><li>修饰动词或形容词，不能修饰名词。</li></ul></div><div class="vocab-card"><h2 id="inappropriate" tabindex="-1"><a class="header-anchor" href="#inappropriate"><span>Inappropriate</span></a></h2><p class="vc-meta"><strong>/ˌɪnəˈprəʊpriət/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>不适当的，不合适的（场合、用途、行为）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>inappropriate behaviour</td><td>不当行为</td></tr><tr><td>inappropriate for</td><td>不适合……</td></tr><tr><td>inappropriate use of land</td><td>土地的不当利用</td></tr><tr><td>socially inappropriate</td><td>不合社交规范的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows inappropriate land use within the buffer zone.</p><blockquote><p>该地图显示了缓冲区内不当的土地利用方式。</p></blockquote><p><strong>Writing Task 2</strong> Building on floodplains is an inappropriate use of land in a changing climate.</p><blockquote><p>在气候变化背景下，在洪泛平原上建房属于不当的土地利用。</p></blockquote><p><strong>Speaking</strong> Jokes about that are completely inappropriate here.</p><blockquote><p>在这儿开那种玩笑非常不合适。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>unsuitable</td><td>不合适的</td><td>偏&quot;不匹配&quot;，语气较中性</td></tr><tr><td>improper</td><td>不恰当的</td><td>带礼仪、规范色彩</td></tr><tr><td>unfitting</td><td>不相称的</td><td>书面，语气较轻</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>in-</em>（不）+ <em>appropriate</em>（恰当的）← <em>ad-</em>（向）+ <em>proprius</em>（自己的）</li><li><strong>Family:</strong> inappropriate 不合适的 / appropriate 合适的 / appropriation 拨款；挪用 / properly 恰当地</li><li><strong>Memory Tip:</strong> appropriate 原义是&quot;使之成为自己的&quot;，引申为&quot;合乎场合的&quot;。加 in- 就是不合场合。写作里 inappropriate use of land 是现成的高分表达。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 in-ap-pro-pri-ate，注意中间三个 p。</li><li>介词常用 for：inappropriate for children。</li><li>说&quot;不合适做某事&quot;用 it is inappropriate to do，不用 <s>inappropriate doing</s>。</li></ul></div><div class="vocab-card"><h2 id="abnormal" tabindex="-1"><a class="header-anchor" href="#abnormal"><span>Abnormal</span></a></h2><p class="vc-meta"><strong>/æbˈnɔːml/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>反常的，异常的（偏离常态）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>abnormal weather</td><td>反常天气</td></tr><tr><td>abnormal behaviour</td><td>异常行为</td></tr><tr><td>abnormal levels of</td><td>异常水平的</td></tr><tr><td>an abnormal increase</td><td>异常增长</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows abnormal rainfall in the region during 2019.</p><blockquote><p>该图表显示了该地区 2019 年的异常降水。</p></blockquote><p><strong>Writing Task 2</strong> Abnormal sea temperatures are bleaching coral reefs across the region.</p><blockquote><p>异常的海水温度正导致该区域珊瑚礁白化。</p></blockquote><p><strong>Speaking</strong> The doctor said the results were abnormal but not dangerous.</p><blockquote><p>医生说结果异常，但不危险。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>unusual</td><td>不寻常的</td><td>最中性，不带诊断意味</td></tr><tr><td>anomalous</td><td>异常的</td><td>学术用语，强调偏离规律</td></tr><tr><td>aberrant</td><td>偏离常态的</td><td>书面，多用于行为、生物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>ab-</em>（离开）+ <em>norma</em>（标准）+ <em>-alis</em> → 偏离标准的</li><li><strong>Family:</strong> abnormal 反常的 / abnormality 异常 / normal 正常的 / norm 标准，常态</li><li><strong>Memory Tip:</strong> ab-（离开）+ norm（标准）= 离开标准线。医学与气候学都爱用它：abnormal cells（异常细胞）、abnormal rainfall（异常降水）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>形容天气&quot;奇怪&quot;用 strange 更自然，abnormal 偏技术判断。</li><li>名词是 abnormality，不是 <s>abnormalness</s>。</li><li>拼写 ab-normal，别与 <s>abnomal</s> 混。</li></ul></div><div class="vocab-card"><h2 id="rural" tabindex="-1"><a class="header-anchor" href="#rural"><span>Rural</span></a></h2><p class="vc-meta"><strong>/ˈrʊərəl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>乡村的，农村的</li><li>田园的，农业的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rural areas</td><td>农村地区</td></tr><tr><td>the rural population</td><td>农村人口</td></tr><tr><td>rural development</td><td>乡村发展</td></tr><tr><td>rural-urban migration</td><td>城乡人口迁移</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows rural land being converted to housing between 2000 and 2020.</p><blockquote><p>该地图显示了 2000 至 2020 年间农村土地被转为住宅用地的情况。</p></blockquote><p><strong>Writing Task 2</strong> Rural depopulation has left schools and clinics without enough users to stay open.</p><blockquote><p>农村人口流失使学校和诊所的使用者不足，难以为继。</p></blockquote><p><strong>Speaking</strong> I grew up in a rural area — the nearest shop was ten miles away.</p><blockquote><p>我在农村长大，最近的商店在十英里外。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>countryside</td><td>乡村</td><td>名词，需加 the</td></tr><tr><td>agricultural</td><td>农业的</td><td>强调产业，非居住形态</td></tr><tr><td>pastoral</td><td>田园的</td><td>文学化，带理想色彩</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>ruralis</em> ← <em>rus</em>（乡村、田地）</li><li><strong>Family:</strong> rural 乡村的 / rustic 质朴的；乡野的 / rusticity 乡野气</li><li><strong>Memory Tip:</strong> rus = 田地。rural 与 urban 是一对必备反义词，写作里 rural-urban migration（城乡迁移）几乎是人口话题的标配表达。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 rural 单 r，不是 <s>rurral</s>。</li><li>&quot;乡下&quot;作名词用 the countryside，不说 <s>the rural</s>。</li><li>与 urban 成对使用，别在段落里混用 urban/rural 指同一批人。</li></ul></div><div class="vocab-card"><h2 id="suburb" tabindex="-1"><a class="header-anchor" href="#suburb"><span>Suburb</span></a></h2><p class="vc-meta"><strong>/ˈsʌbɜːb/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>郊区，近郊（多指城市边缘的居住区）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>in the suburbs</td><td>在郊区</td></tr><tr><td>a suburb of</td><td>……的一个郊区</td></tr><tr><td>the outer suburbs</td><td>远郊</td></tr><tr><td>suburban area</td><td>郊区地带</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the city expanding into its northern suburbs.</p><blockquote><p>该地图显示了城市向北郊扩张的情况。</p></blockquote><p><strong>Writing Task 2</strong> Suburbs consume far more land per person than inner-city neighbourhoods.</p><blockquote><p>郊区的人均占地远高于市中心社区。</p></blockquote><p><strong>Speaking</strong> We live in a suburb about twenty minutes from the centre.</p><blockquote><p>我们住在离市中心约二十分钟的一个郊区。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>outskirts</td><td>市郊外围</td><td>强调边缘，比 suburb 更外围</td></tr><tr><td>suburbia</td><td>郊区生活</td><td>常带贬义，指中产郊区文化</td></tr><tr><td>commuter belt</td><td>通勤带</td><td>强调往返上班的功能</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>sub-</em>（近、下）+ <em>urbs</em>（城市）→ &quot;城下之地&quot;</li><li><strong>Family:</strong> suburb 郊区 / suburban 郊区的 / suburbanite 郊区居民 / urban 城市的 / urbane 彬彬有礼的</li><li><strong>Memory Tip:</strong> sub（近）+ urbs（城）= 紧挨着城的居住区。urbs 还长出 urban（城市的）、urbane（有城市教养的）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>泛指郊区用复数：in the suburbs。</li><li>suburb 指&quot;一个具体的郊区&quot;，不是&quot;郊区&quot;这个整体概念。</li><li>介词用 in：in a suburb of London。</li></ul></div><div class="vocab-card"><h2 id="outskirts" tabindex="-1"><a class="header-anchor" href="#outskirts"><span>Outskirts</span></a></h2><p class="vc-meta"><strong>/ˈaʊtskɜːts/</strong> · noun · 名词（复数）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>市郊，外围地带（城镇边缘）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>on the outskirts of</td><td>在……的市郊</td></tr><tr><td>the northern outskirts</td><td>北郊</td></tr><tr><td>at the outskirts</td><td>在外围</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a new industrial zone on the outskirts of the city.</p><blockquote><p>该地图显示了城市市郊新建的工业区。</p></blockquote><p><strong>Writing Task 2</strong> Low-income housing is increasingly pushed to the outskirts, far from work and services.</p><blockquote><p>低收入住房正日益被挤到远郊，远离工作地点与公共服务。</p></blockquote><p><strong>Speaking</strong> They live on the outskirts of town, near the ring road.</p><blockquote><p>他们住在城镇边缘，靠近环路。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>periphery</td><td>边缘地带</td><td>学术，强调与中心的对立</td></tr><tr><td>fringe</td><td>边缘</td><td>可指城市边缘或社会边缘</td></tr><tr><td>suburb</td><td>郊区</td><td>指居住区，非泛指外围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>out</em>（外）+ <em>skirts</em>（边缘，原义&quot;裙摆&quot;）</li><li><strong>Family:</strong> outskirts 外围 / skirt 裙子；绕行 / skirting board 踢脚线</li><li><strong>Memory Tip:</strong> skirt 原义是&quot;裙摆&quot;，outskirts 就是城市拖出来的&quot;裙边&quot;——比 suburb 更强调&quot;外围、边缘&quot;，常带&quot;尚未城市化&quot;的意味。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>只用复数：the outskirts，不说 <s>an outskirt</s>。</li><li>介词用 on：on the outskirts of the city，不用 <s>in</s>。</li><li>与 suburb 有别：outskirts 是外围地带，suburb 是成片的居住区。</li></ul></div><div class="vocab-card"><h2 id="adjacent" tabindex="-1"><a class="header-anchor" href="#adjacent"><span>Adjacent</span></a></h2><p class="vc-meta"><strong>/əˈdʒeɪsnt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>邻近的，毗邻的（紧挨着）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>adjacent to</td><td>与……毗邻</td></tr><tr><td>adjacent buildings</td><td>相邻建筑</td></tr><tr><td>adjacent areas</td><td>邻近地区</td></tr><tr><td>immediately adjacent</td><td>紧邻的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a car park adjacent to the station.</p><blockquote><p>该地图显示了紧邻车站的停车场。</p></blockquote><p><strong>Writing Task 2</strong> Communities adjacent to the landfill have reported higher rates of respiratory illness.</p><blockquote><p>垃圾填埋场附近的社区报告了更高的呼吸道疾病发病率。</p></blockquote><p><strong>Speaking</strong> Our room was adjacent to the lift, so it was noisy.</p><blockquote><p>我们的房间紧挨着电梯，所以很吵。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>neighbouring</td><td>邻近的</td><td>泛指周边，不一定相接</td></tr><tr><td>adjoining</td><td>毗连的</td><td>强调共用一墙、直接相连</td></tr><tr><td>bordering</td><td>接壤的</td><td>用于国家、地区边界</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>ad-</em>（向）+ <em>jacere</em>（躺）→ <em>adjacens</em>（躺在旁边的）</li><li><strong>Family:</strong> adjacent 邻近的 / adjacency 邻近 / adjoin 毗连</li><li><strong>Memory Tip:</strong> ad-（向）+ jac（躺）= 躺在旁边。jacere 还长出 project（向前投）、reject（扔回去）、injection（注入）——一个&quot;扔&quot;字串起一串词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词 to 不能省：adjacent to the station。</li><li>adjoining 比 adjacent 更近：共用一墙才叫 adjoining。</li><li>拼写 ad-ja-cent，注意 -cent 结尾。</li></ul></div><div class="vocab-card"><h2 id="environment" tabindex="-1"><a class="header-anchor" href="#environment"><span>Environment</span></a></h2><p class="vc-meta"><strong>/ɪnˈvaɪrənmənt/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>自然环境（the environment）</li><li>环境，氛围（工作、学习环境）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the environment</td><td>自然环境</td></tr><tr><td>environmental protection</td><td>环境保护</td></tr><tr><td>a learning environment</td><td>学习环境</td></tr><tr><td>natural environment</td><td>自然环境</td></tr><tr><td>environmental impact</td><td>环境影响</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows public spending on environmental protection.</p><blockquote><p>该图表显示了用于环境保护的公共支出。</p></blockquote><p><strong>Writing Task 2</strong> Protecting the environment and growing the economy are not mutually exclusive.</p><blockquote><p>保护环境与发展经济并非相互排斥。</p></blockquote><p><strong>Speaking</strong> I work much better in a quiet environment.</p><blockquote><p>在安静的环境里我效率高得多。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>surroundings</td><td>周边环境</td><td>多指身边的物理环境</td></tr><tr><td>setting</td><td>场景</td><td>指故事、事件的背景</td></tr><tr><td>habitat</td><td>栖息地</td><td>生态学，指物种生存环境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>environ</em>（围绕）+ <em>-ment</em></li><li><strong>Family:</strong> environment 环境 / environmental 环境的 / environmentalist 环保人士 / environs 周边地区</li><li><strong>Memory Tip:</strong> 指&quot;自然环境&quot;时加 the：protect the environment。指&quot;氛围&quot;时不加：a working environment。两种用法在同一段里出现很常见。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>自然环境义加冠词：the environment。</li><li>形容词是 environmental，不是 <s>environmental</s> 拼错为 environ-mental 分写。</li><li>environment 可数，指多种环境：different learning environments。</li></ul></div><div class="vocab-card"><h2 id="surrounding" tabindex="-1"><a class="header-anchor" href="#surrounding"><span>Surrounding</span></a></h2><p class="vc-meta"><strong>/səˈraʊndɪŋ/</strong> · adj · 形容词 / noun · 名词（复数）</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：周围的，附近的</li><li>名词（surroundings）：周边环境</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the surrounding area</td><td>周边地区</td></tr><tr><td>the surrounding countryside</td><td>周边乡村</td></tr><tr><td>the surroundings</td><td>周边环境</td></tr><tr><td>adapt to new surroundings</td><td>适应新环境</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the town and its surrounding farmland.</p><blockquote><p>该地图显示了该镇及其周边的农田。</p></blockquote><p><strong>Writing Task 2</strong> Cities increasingly draw water from distant surrounding regions.</p><blockquote><p>城市越来越多地从远处周边地区取水。</p></blockquote><p><strong>Speaking</strong> The house is nice, but the surroundings are noisy.</p><blockquote><p>房子不错，但周边很吵。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>neighbouring</td><td>邻近的</td><td>强调相邻，不一定环绕</td></tr><tr><td>adjacent</td><td>毗邻的</td><td>强调紧挨着</td></tr><tr><td>environs</td><td>周边地区</td><td>书面，多用于城市</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>sur-</em>（外、上）+ <em>round</em>（环绕）</li><li><strong>Family:</strong> surround 包围 / surrounding 周围的 / surroundings 周边环境</li><li><strong>Memory Tip:</strong> 记一个字母的差别：<strong>形容词 surrounding</strong>（the surrounding area）+ 名词 <strong>surroundings</strong>（带 s，表&quot;环境&quot;）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作定语用单数：the surrounding area。</li><li>表&quot;环境&quot;用复数名词：the surroundings。</li><li>别把 surrounding 单独当名词用：<s>in the surrounding</s> ✘。</li></ul></div><div class="vocab-card"><h2 id="condition" tabindex="-1"><a class="header-anchor" href="#condition"><span>Condition</span></a></h2><p class="vc-meta"><strong>/kənˈdɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>条件（前提）</li><li>状况，状态；（复数）环境条件</li><li>疾病</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>weather conditions</td><td>天气条件</td></tr><tr><td>in good condition</td><td>状况良好</td></tr><tr><td>on condition that</td><td>条件是</td></tr><tr><td>living conditions</td><td>生活条件</td></tr><tr><td>a medical condition</td><td>疾病</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares living conditions in rural and urban areas.</p><blockquote><p>该图表比较了农村与城市的生活条件。</p></blockquote><p><strong>Writing Task 2</strong> Under current conditions, the target is unlikely to be met.</p><blockquote><p>在现有条件下，该目标不太可能实现。</p></blockquote><p><strong>Speaking</strong> The car&#39;s in great condition for its age.</p><blockquote><p>这车按车龄来说状况很好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>state</td><td>状态</td><td>强调某一时刻的状况</td></tr><tr><td>situation</td><td>形势</td><td>更宏观，含人与事的格局</td></tr><tr><td>circumstances</td><td>情形</td><td>多指影响决定的客观情况</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>condicio</em>（约定、状况）</li><li><strong>Family:</strong> condition 条件；状况 / conditional 有条件的 / conditioner 护发素；调节剂</li><li><strong>Memory Tip:</strong> 复数 conditions 常指&quot;环境条件&quot;：weather conditions、working conditions、living conditions。单数多指&quot;状态&quot;或&quot;前提&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表&quot;环境条件&quot;用复数：under these conditions。</li><li>on condition that 后接完整从句，that 不能省的语境较多。</li><li>conditional 是形容词&quot;有条件的&quot;，别与 conditional 混为名词。</li></ul></div><div class="vocab-card"><h2 id="situation" tabindex="-1"><a class="header-anchor" href="#situation"><span>Situation</span></a></h2><p class="vc-meta"><strong>/ˌsɪtʃuˈeɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形势，情况，局面</li><li>（建筑、城镇的）位置</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the current situation</td><td>当前形势</td></tr><tr><td>a difficult situation</td><td>困难的处境</td></tr><tr><td>in a situation where</td><td>在……的情况下</td></tr><tr><td>the economic situation</td><td>经济形势</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the situation of the new reservoir relative to the town.</p><blockquote><p>该地图显示了新水库相对于城镇的位置。</p></blockquote><p><strong>Writing Task 2</strong> In a situation where water is scarce, pricing alone cannot allocate it fairly.</p><blockquote><p>在水资源稀缺的情况下，仅靠定价无法公平分配。</p></blockquote><p><strong>Speaking</strong> It&#39;s an awkward situation — I don&#39;t want to take sides.</p><blockquote><p>这局面挺尴尬，我不想站队。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>circumstances</td><td>情形</td><td>强调客观条件</td></tr><tr><td>position</td><td>处境</td><td>含被动、不利的意味</td></tr><tr><td>scenario</td><td>设想情形</td><td>多用于推演假设</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>situare</em>（放置）← <em>situs</em>（位置）</li><li><strong>Family:</strong> situation 情况；位置 / situate 使位于 / situated 位于的 / situational 情境的</li><li><strong>Memory Tip:</strong> 原义是&quot;位置&quot;（the situation of the house），今多指&quot;情况&quot;。be situated in 表&quot;位于&quot;，地图描述常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 in：in a situation where…。</li><li>可数：a difficult situation / situations。</li><li>&quot;位于&quot;用 be situated in，不用 <s>situate in</s> 主动形式。</li></ul></div><div class="vocab-card"><h2 id="nature" tabindex="-1"><a class="header-anchor" href="#nature"><span>Nature</span></a></h2><p class="vc-meta"><strong>/ˈneɪtʃə(r)/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大自然，自然界</li><li>本性，天性；（事物的）性质</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>in nature</td><td>在自然界中</td></tr><tr><td>human nature</td><td>人性</td></tr><tr><td>by nature</td><td>天生地</td></tr><tr><td>the nature of</td><td>……的性质</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the changing nature of household energy use.</p><blockquote><p>该图表显示了家庭能源使用性质的变化。</p></blockquote><p><strong>Writing Task 2</strong> The scale of the problem is global in nature and cannot be solved locally.</p><blockquote><p>该问题的规模本质上是全球性的，无法在地方层面解决。</p></blockquote><p><strong>Speaking</strong> I love being out in nature — it resets me.</p><blockquote><p>我喜欢待在大自然里，那能让我放松下来。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>the natural world</td><td>自然界</td><td>更明确，避免歧义</td></tr><tr><td>character</td><td>性质</td><td>指特征、性格</td></tr><tr><td>essence</td><td>本质</td><td>强调根本属性</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>natura</em>（天性）← <em>nasci</em>（出生）</li><li><strong>Family:</strong> nature 自然；本性 / natural 自然的 / naturally 自然地 / naturalise 使归化</li><li><strong>Memory Tip:</strong> 两义要分清：大自然（in nature，不加 the）与本性（human nature / the nature of X）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;在自然界&quot;是 in nature，不加 the。</li><li>&quot;……的性质&quot;用 the nature of，别写 <s>the nature</s>。</li><li>by nature 表&quot;天生地&quot;，与 in nature 不同。</li></ul></div><div class="vocab-card"><h2 id="natural" tabindex="-1"><a class="header-anchor" href="#natural"><span>Natural</span></a></h2><p class="vc-meta"><strong>/ˈnætʃrəl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>自然的，天然的</li><li>正常的，合乎常理的</li><li>天生的（天赋）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>natural resources</td><td>自然资源</td></tr><tr><td>natural gas</td><td>天然气</td></tr><tr><td>natural disaster</td><td>自然灾害</td></tr><tr><td>natural habitat</td><td>自然栖息地</td></tr><tr><td>it is natural that</td><td>……是正常的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the distribution of natural resources across the region.</p><blockquote><p>该地图显示了该地区自然资源的分布。</p></blockquote><p><strong>Writing Task 2</strong> Natural systems recover more slowly than was once assumed.</p><blockquote><p>自然系统的恢复速度比人们过去认为的要慢。</p></blockquote><p><strong>Speaking</strong> It&#39;s natural to feel nervous before an exam.</p><blockquote><p>考试前紧张是很正常的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>innate</td><td>天生的</td><td>强调与生俱来</td></tr><tr><td>organic</td><td>有机的</td><td>指无化学添加</td></tr><tr><td>native</td><td>原生的</td><td>指本地物种</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>naturalis</em> ← <em>natura</em>（自然）</li><li><strong>Family:</strong> natural 自然的 / nature 自然 / naturally 自然地；当然 / naturalist 博物学家</li><li><strong>Memory Tip:</strong> 三义一条线：天然的（natural gas）→ 正常的（it&#39;s natural to…）→ 天生的（a natural talent）。反义词是 artificial。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>natural 与 artificial 是标准反义对。</li><li>&quot;自然灾害&quot;是 natural disaster，不用 <s>nature disaster</s>。</li><li>naturally 在口语里可表&quot;当然&quot;（Naturally, I agreed）。</li></ul></div><div class="vocab-card"><h2 id="artificial" tabindex="-1"><a class="header-anchor" href="#artificial"><span>Artificial</span></a></h2><p class="vc-meta"><strong>/ˌɑːtɪˈfɪʃl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>人工的，人造的（非天然）</li><li>虚假的，做作的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>artificial intelligence</td><td>人工智能</td></tr><tr><td>artificial light</td><td>人造光</td></tr><tr><td>artificial fertiliser</td><td>化肥</td></tr><tr><td>artificial lake</td><td>人工湖</td></tr><tr><td>artificial sweetener</td><td>人工甜味剂</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows artificial lakes created to store irrigation water.</p><blockquote><p>该地图显示了为蓄灌溉水而建的人工湖。</p></blockquote><p><strong>Writing Task 2</strong> Artificial intelligence is now used to predict crop yields and water demand.</p><blockquote><p>人工智能如今被用于预测作物产量与用水需求。</p></blockquote><p><strong>Speaking</strong> The lighting was artificial, so all the photos came out orange.</p><blockquote><p>光线是人造的，所以照片全发黄。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>man-made</td><td>人造的</td><td>口语化，强调人类制造</td></tr><tr><td>synthetic</td><td>合成的</td><td>特指化学合成材料</td></tr><tr><td>fake</td><td>假的</td><td>带欺骗意味，贬义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>artificium</em>（技艺）← <em>ars</em>（技艺）+ <em>facere</em>（做）</li><li><strong>Family:</strong> artificial 人工的 / artificially 人工地 / artifice 诡计 / artisan 工匠</li><li><strong>Memory Tip:</strong> ars（技艺）+ facere（做）= 用技艺做出来的。所以 AI 就是 artificial intelligence；而形容人&quot;做作&quot;也用 artificial。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 ar-ti-fi-cial，注意 -cial 结尾。</li><li>artificial（非天然）与 synthetic（化学合成）侧重不同。</li><li>形容人时说 artificial 意为&quot;做作&quot;，是贬义。</li></ul></div><div class="vocab-card"><h2 id="synthetic" tabindex="-1"><a class="header-anchor" href="#synthetic"><span>Synthetic</span></a></h2><p class="vc-meta"><strong>/sɪnˈθetɪk/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>合成的，人造的（化学方法制成）</li><li>名词：合成材料</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>synthetic fibres</td><td>合成纤维</td></tr><tr><td>synthetic rubber</td><td>合成橡胶</td></tr><tr><td>synthetic materials</td><td>合成材料</td></tr><tr><td>synthetic chemicals</td><td>合成化学品</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the price of natural and synthetic rubber.</p><blockquote><p>该图表比较了天然橡胶与合成橡胶的价格。</p></blockquote><p><strong>Writing Task 2</strong> Synthetic fertilisers boosted yields but polluted waterways across the region.</p><blockquote><p>合成化肥提高了产量，却污染了整个地区的水道。</p></blockquote><p><strong>Speaking</strong> This jacket&#39;s synthetic — it doesn&#39;t breathe at all.</p><blockquote><p>这件夹克是化纤的，完全不透气。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>artificial</td><td>人造的</td><td>范围更广，含灯光、湖泊</td></tr><tr><td>man-made</td><td>人造的</td><td>泛指人类制造</td></tr><tr><td>chemical</td><td>化学的</td><td>强调化学成分，非&quot;合成&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>synthesis</em>（合成）= <em>syn-</em>（一起）+ <em>thesis</em>（放置）</li><li><strong>Family:</strong> synthetic 合成的 / synthesis 综合；合成 / synthesise 合成 / synthesiser 合成器</li><li><strong>Memory Tip:</strong> syn-（一起）+ thesis（放）= 把东西放到一起造出来。所以 synthetic 强调&quot;化学合成&quot;，与 natural 相对。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>synthetic 多指化学合成材料；artificial 范围更广（人工光、人工湖）。</li><li>动词是 synthesise（英式）/ synthesize（美式）。</li><li>拼写 syn-thet-ic，注意 -thet-。</li></ul></div><div class="vocab-card"><h2 id="petrol" tabindex="-1"><a class="header-anchor" href="#petrol"><span>Petrol</span></a></h2><p class="vc-meta"><strong>/ˈpetrəl/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>汽油（英式）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a petrol station</td><td>加油站</td></tr><tr><td>petrol prices</td><td>汽油价格</td></tr><tr><td>unleaded petrol</td><td>无铅汽油</td></tr><tr><td>run out of petrol</td><td>汽油耗尽</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares petrol and diesel consumption over two decades.</p><blockquote><p>该图表比较了二十年间汽油与柴油的消费量。</p></blockquote><p><strong>Writing Task 2</strong> Petrol cars will be phased out in several countries by 2035.</p><blockquote><p>若干国家将在 2035 年前逐步淘汰汽油车。</p></blockquote><p><strong>Speaking</strong> We ran out of petrol ten miles from the nearest station.</p><blockquote><p>我们在离最近加油站十英里的地方没油了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gas</td><td>汽油</td><td>美式口语说法</td></tr><tr><td>gasoline</td><td>汽油</td><td>美式书面说法</td></tr><tr><td>fuel</td><td>燃料</td><td>泛指，含柴油、电</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>pétrole</em> ← 拉丁 <em>petroleum</em>（岩中之油）</li><li><strong>Family:</strong> petrol 汽油 / petroleum 石油 / petrochemical 石化产品</li><li><strong>Memory Tip:</strong> 层级关系：petroleum（石油，总称）→ petrol（汽油，提炼品）。英式 petrol 对应美式 gas / gasoline。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式 petrol、美式 gas，同一篇内保持一致。</li><li>加油站英式 petrol station、美式 gas station。</li><li>petrol 不可数：不说 <s>a petrol</s>。</li></ul></div><div class="vocab-card"><h2 id="gas" tabindex="-1"><a class="header-anchor" href="#gas"><span>Gas</span></a></h2><p class="vc-meta"><strong>/ɡæs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>气体</li><li>燃气，天然气</li><li>（美式）汽油</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>natural gas</td><td>天然气</td></tr><tr><td>greenhouse gas</td><td>温室气体</td></tr><tr><td>gas emissions</td><td>气体排放</td></tr><tr><td>gas station</td><td>加油站（美式）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares emissions of greenhouse gases by sector.</p><blockquote><p>该图表比较了各部门的温室气体排放。</p></blockquote><p><strong>Writing Task 2</strong> Burning gas for electricity emits roughly half the CO2 of coal.</p><blockquote><p>用天然气发电的二氧化碳排放约为燃煤的一半。</p></blockquote><p><strong>Speaking</strong> The heating runs on gas, so the bill&#39;s gone up again.</p><blockquote><p>供暖用的是燃气，账单又涨了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vapour</td><td>蒸汽</td><td>指气态水或挥发物</td></tr><tr><td>fuel</td><td>燃料</td><td>泛指，含油、煤</td></tr><tr><td>gasoline</td><td>汽油</td><td>美式书面语</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>khaos</em>（混沌）→ 荷兰语 <em>gas</em>（范·海尔蒙特造词）</li><li><strong>Family:</strong> gas 气体 / gaseous 气态的 / gasify 气化 / greenhouse gas 温室气体</li><li><strong>Memory Tip:</strong> 三义按语境判断：气体（oxygen is a gas）、燃气（cook with gas）、汽油（美式 get gas）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>温室气体用复数：greenhouse gases。</li><li>可数，指&quot;一种气体&quot;：a noble gas。</li><li>美式 gas 可指汽油，英式不用这个义。</li></ul></div><div class="vocab-card"><h2 id="gasoline" tabindex="-1"><a class="header-anchor" href="#gasoline"><span>Gasoline</span></a></h2><p class="vc-meta"><strong>/ˈɡæsəliːn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>汽油（美式，书面语）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>gasoline prices</td><td>汽油价格</td></tr><tr><td>a gasoline engine</td><td>汽油发动机</td></tr><tr><td>leaded gasoline</td><td>含铅汽油</td></tr><tr><td>a gasoline station</td><td>加油站（美式）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows average gasoline prices over a decade.</p><blockquote><p>该图表显示了十年间的平均汽油价格。</p></blockquote><p><strong>Writing Task 2</strong> Taxing gasoline is one of the most efficient ways to cut car use.</p><blockquote><p>对汽油征税是减少汽车使用最有效的手段之一。</p></blockquote><p><strong>Speaking</strong> Gasoline here is much cheaper than back home.</p><blockquote><p>这里的汽油比国内便宜多了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>petrol</td><td>汽油</td><td>英式说法</td></tr><tr><td>gas</td><td>汽油</td><td>美式口语缩写</td></tr><tr><td>fuel</td><td>燃料</td><td>泛指所有燃料</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>gas</em> + <em>-ol</em> + <em>-ine</em>（19 世纪商品名，后通用化）</li><li><strong>Family:</strong> gasoline 汽油 / gas 气体；汽油 / gasohol 乙醇汽油</li><li><strong>Memory Tip:</strong> 三个&quot;汽油&quot;按地域分：英式 petrol、美式书面 gasoline、美式口语 gas。写雅思时选一个并全篇统一。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>美式 gasoline、英式 petrol，不要混用。</li><li>不可数：不说 <s>a gasoline</s>。</li><li>gasoline engine 指&quot;汽油发动机&quot;，与 diesel engine 相对。</li></ul></div><div class="vocab-card"><h2 id="petroleum" tabindex="-1"><a class="header-anchor" href="#petroleum"><span>Petroleum</span></a></h2><p class="vc-meta"><strong>/pəˈtrəʊliəm/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>石油（原油及其制品的总称）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the petroleum industry</td><td>石油工业</td></tr><tr><td>petroleum products</td><td>石油产品</td></tr><tr><td>petroleum reserves</td><td>石油储量</td></tr><tr><td>petroleum-based</td><td>石油基的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows petroleum exports as a share of total government revenue.</p><blockquote><p>该图表显示了石油出口占政府总收入的比重。</p></blockquote><p><strong>Writing Task 2</strong> Petroleum-based plastics are difficult to replace at scale.</p><blockquote><p>石油基塑料很难大规模替代。</p></blockquote><p><strong>Speaking</strong> The country&#39;s economy depends almost entirely on petroleum.</p><blockquote><p>该国经济几乎完全依赖石油。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>crude oil</td><td>原油</td><td>特指未提炼的石油</td></tr><tr><td>oil</td><td>石油</td><td>口语简称，也可指食用油</td></tr><tr><td>fossil fuel</td><td>化石燃料</td><td>含煤、石油、天然气</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>petra</em>（岩石）+ <em>oleum</em>（油）= &quot;岩石中的油&quot;</li><li><strong>Family:</strong> petroleum 石油 / petrol 汽油 / petrochemical 石化产品 / petrodollar 石油美元</li><li><strong>Memory Tip:</strong> petra（岩）+ oleum（油）= 石头里的油。层级：petroleum 是总称，petrol 只是其中的汽油，crude oil 是未提炼的原油。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：不说 <s>a petroleum</s>。</li><li>petroleum（石油总称）≠ petrol（汽油）。</li><li>&quot;原油&quot;用 crude oil / crude petroleum，不能说 raw petroleum。</li></ul></div>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};